package com.gamelab.pattern.strategy;
import com.gamelab.domain.Enemy;
/** Boss movement strategy with explicit ability requests for the game controller. */
public final class BossBehavior implements EnemyBehavior { public enum Ability { AREA_ATTACK, SUMMON, TELEPORT, POISON_CLOUD, FIRE_ZONE, SHADOW_CLONE, ICE_PROJECTILE, SHOCKWAVE } private final double preferredDistance, abilityInterval; private double elapsed; private Ability pending; public BossBehavior(){this(105,6);} public BossBehavior(double distance,double interval){if(distance<=0||interval<=0)throw new IllegalArgumentException("Values must be positive");preferredDistance=distance;abilityInterval=interval;} public void update(Enemy e,double x,double y,double dt){double d=Math.hypot(x-e.getX(),y-e.getY());if(d>preferredDistance*1.25)e.moveTowards(x,y,dt);else if(d<preferredDistance*.65)e.moveAway(x,y,dt);elapsed+=dt;if(elapsed>=abilityInterval&&pending==null){elapsed-=abilityInterval;pending=Ability.AREA_ATTACK;}} public void requestAbility(Ability ability){if(pending==null)pending=ability;} public Ability consumeAbility(){Ability a=pending;pending=null;return a;} }
